//! Cargo-driven `stortest.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is stortest-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The C left, and its part of cmake's C rule; reactos-link adds what every C
    // compile shares from reactos-link/cflags/c.<arch>.flags (Linker::c_compiled).
    let c_sources: &[&str] = &["base/applications/stortest/rust_varargs_shim.c"];
    let c_includes: &[&str] = &[
        "@build/base/applications/stortest",
        "base/applications/stortest",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let c_flags: &[&str] = match arch.as_str() {
        "x86" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        "x86_64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "-U_X86_",
            "-UWIN32",
            "@core",
        ],
        "aarch64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        _ => unreachable!(),
    };
    let c_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_mainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "mainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "mainCRTStartup"),
        o => panic!("stortest-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("stortest-rust")
        .c_compiled("stortest_shims", c_sources, c_includes, c_flags, c_defines)
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
